底图图源：Peter Pan 图床国内，挂了群里戳
/* ★私人志_夜幽华@夜行性鲨鱼
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎），无言退群的请不要用我的美化……
带符号💜的地方是自定义文字区域
气泡默认380px，太大太小可自行调换
想换图链的搜索关键词url */
/* ★港风改色 */
/* ★1. 气泡核心结构与封面设计 */
body.bubblechat .mes,body.bubblechat .mes[is_user="true"],.mes{padding:20px!important;padding-top:240px!important;padding-bottom:40px!important;border-radius:0!important;border:1px solid #C89D3B!important;box-shadow:6px 6px 0 #4F1414!important;max-width:380px!important;margin:40px auto 25px auto!important;position:relative;background-color:#2F0A0A!important;background-image:linear-gradient(145deg, #3A0E0E, #1E0505)!important;box-sizing:border-box!important;overflow:visible!important}
.mes_block{width:100%!important;max-width:100%!important;padding:0!important;margin:0!important}
.mes_text{padding:0!important;margin:0!important;text-align:justify!important;text-justify:inter-ideograph!important;line-height:1.8!important;color:#F2E6D5!important}
.mes::before{content:''!important;position:absolute!important;top:15px!important;left:15px!important;right:15px!important;height:140px!important;background-image:url('https://iili.io/BUKGy6F.jpg')!important;background-size:cover!important;background-position:center 30%!important;filter:sepia(0.4) contrast(1.3) brightness(0.8)!important;z-index:1;border:1px solid #B47D2A}
.mesAvatarWrapper{position:absolute!important;top:70px!important;left:25px!important;width:90px!important;height:115px!important;z-index:10!important;background:#3D0D0D!important;padding:5px!important;padding-bottom:30px!important;border:1px solid #D4A43A!important;box-shadow:2px 4px 8px rgba(70,20,0,0.6)!important;overflow:hidden!important;display:block!important}
.mesAvatarWrapper .avatar{width:80px!important;height:80px!important;position:relative!important;overflow:hidden!important;display:block!important;margin:0 auto!important}
/* 修复头像缩小问题：精准锁定封面头像，全填充覆盖 */
.mesAvatarWrapper .avatar img{object-fit:cover!important;width:100%!important;height:100%!important;filter:sepia(0.3) contrast(1.2)!important;display:block!important}
.mesAvatarWrapper::before{content:"PRIVATE MANUSCRIPT"!important;/* 💜一般来说，没有改的必要 */position:absolute!important;left:4px!important;top:40px!important;transform:rotate(-90deg) translateY(-50%)!important;transform-origin:left center!important;font-size:7px!important;color:#E2B86B!important;letter-spacing:1px!important;white-space:nowrap!important;z-index:10}
.mesAvatarWrapper::after{content:"港"!important;/* 💜 */position:absolute!important;right:2px!important;bottom:2px!important;width:18px!important;height:18px!important;color:#D4A43A!important;font-size:10px!important;line-height:16px!important;text-align:center!important;font-weight:900!important;z-index:10!important;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="r"><feTurbulence type="fractalNoise" baseFrequency="0.15" numOctaves="3"/><feDisplacementMap in="SourceGraphic" scale="8"/></filter><rect x="5" y="5" width="90" height="90" fill="none" stroke="%23D4A43A" stroke-width="10" filter="url(%23r)"/></svg>')!important;background-size:contain!important;background-repeat:no-repeat!important;filter:opacity(.85)!important}
.mes .name_text{position:absolute!important;left:130px!important;top:165px!important;font-size:1.4em!important;font-weight:700!important;color:#F8E2B0!important;letter-spacing:2px!important;z-index:10;background:#3C0E0E!important;padding:2px 8px!important;border:1px solid #D6A841!important;text-shadow:1px 1px 0 #2F0707!important}
.mes .name_text::after{content:"檕我。"!important;/* 💜 */display:block!important;position:absolute;left:0;top:-18px;font-size:8px!important;letter-spacing:1px!important;color:#E5CD94!important;background:#5A1A1A!important;padding:2px 4px!important;white-space:nowrap}
.mes .mesIDDisplay{position:absolute!important;bottom:10px!important;left:15px!important;background:0 0!important;color:#C9A75B!important;text-shadow:0 0 2px #1E0404,0 0 1px #1E0404!important;font-size:7px!important;z-index:15!important}
.mes .tokenCounterDisplay{position:absolute!important;bottom:18px!important;left:15px!important;background:0 0!important;color:#C9A75B!important;text-shadow:0 0 2px #1E0404,0 0 1px #1E0404!important;font-size:7px!important;z-index:15!important}
.mes .mes_timer{position:absolute!important;bottom:26px!important;left:15px!important;background:0 0!important;color:#C9A75B!important;text-shadow:0 0 2px #1E0404,0 0 1px #1E0404!important;font-size:7px!important;z-index:15!important}
.mes .timestamp{position:absolute!important;right:25px!important;top:130px!important;background:#3C0E0E!important;color:#D6B06A!important;font-size:9px!important;padding:2px 6px!important;border:1px solid #D4A43A!important;z-index:10!important;font-style:normal;border-top:1px solid #D4A43A;width:auto}

/* ★2. UI 全局深度重构 */
*{border-radius:0!important}
.text_pole,textarea,select,.menu_button,.character_select,.group_select,input[type="text"],input[type="number"]{background-color:#2E0D0D!important;border:1px solid #B5822A!important;color:#F0DEC0!important;border-radius:0!important;box-shadow:2px 2px 0 #4F1414!important;transition:all .2s ease}
.text_pole:focus,textarea:focus,select:focus{border-color:#E0B354!important;box-shadow:2px 2px 0 rgba(212,164,58,0.4)!important;outline:none!important}
.menu_button{background-color:#351010!important;font-weight:700}
.menu_button:hover{background-color:#4A1A1A!important;color:#FFE8B0!important}
.inline-drawer-toggle,.list-group-item,.drawer-content .list-group-item,#extensions_menu .inline-drawer-toggle{background:#2E0D0D!important;background-image:none!important;border:1px solid #C6972E!important;margin:6px 8px!important;box-shadow:2px 2px 0 #4F1414!important;color:#F0DEC0!important;font-weight:700!important;padding:10px 15px!important;transition:all .2s ease!important}
.inline-drawer-toggle:hover,.list-group-item:hover{background:#4A1A1A!important;border-color:#E0B354!important;transform:translate(-1px,-1px);box-shadow:3px 3px 0 rgba(212,164,58,0.5)!important;color:#FFEDC0!important}
.inline-drawer-toggle i,.inline-drawer-toggle .fa-chevron-down,.inline-drawer-toggle .fa-chevron-right,.inline-drawer-icon{color:#D4A94A!important;text-shadow:none!important}
#right-nav h4,#left-nav h4,.inline-drawer-header h4,.standoutHeader,.drawer-content h4{background:#1F0505!important;color:#E6C27A!important;border:1px solid #1F0505!important;padding:8px 12px!important;margin:15px 8px 10px 8px!important;letter-spacing:2px!important;text-transform:uppercase;font-size:14px!important;box-shadow:3px 3px 0 #2F0707!important;text-align:center!important;text-shadow:none!important}
.mes_text h1,.mes_text h2,.mes_text h3,.mes_text h4{background:transparent!important;color:#F4E1C0!important;border:none!important;border-bottom:1px solid #C6972E!important;box-shadow:none!important;margin:15px 0 10px 0!important;padding:0 0 5px 0!important;text-align:left!important}
#completion_prompt_manager_list{background-color:transparent!important;border:none!important}#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,#completion_prompt_manager_list .text_muted,.completion_prompt_manager_prompt_name{color:#E0C488!important;opacity:1!important;-webkit-text-fill-color:#E0C488!important;text-shadow:none!important}
input[type="range"]{-webkit-appearance:none!important;appearance:none!important;background:#4E1C1C!important;height:3px!important;border:none!important;box-shadow:none!important;outline:none!important;filter:none!important;mix-blend-mode:normal!important;opacity:1!important;overflow:visible!important}
/* 保持滑块图标原色 */
input[type="range"]::-webkit-slider-thumb,input[type="range"]::-moz-range-thumb{-webkit-appearance:none!important;width:34px!important;height:24px!important;background:url('https://files.catbox.moe/dtkz8w.png')center/contain no-repeat!important;border:0!important;border-radius:0!important;filter:drop-shadow(1px 1px 2px rgba(80,20,0,0.8))!important}
input[type="checkbox"]{border-radius:0!important;-webkit-appearance:none;appearance:none;background:0 0!important;border:1px solid #C6972E!important;width:16px;height:16px;position:relative;vertical-align:middle;cursor:pointer;outline:none!important}input[type="checkbox"]:checked{border-color:#E0B354!important;background:0 0!important}input[type="checkbox"]::before{content:none!important}input[type="checkbox"]:checked::after{content:''!important;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)!important;width:14px;height:14px;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg')center/cover no-repeat!important;filter:contrast(1.2) invert(.8) sepia(0.3)!important}
::-webkit-scrollbar{display:none}
/* 顶栏常亮并增加毛玻璃背景 */
#top-bar{position:absolute!important;top:0!important;left:0!important;right:0!important;width:100%!important;padding:4px 0!important;z-index:3005!important;opacity:1!important;background:rgba(60,20,10,0.6)!important;backdrop-filter:blur(4px)!important;-webkit-backdrop-filter:blur(4px)!important;transition:all .3s ease!important;box-shadow:0 2px 5px rgba(40,5,0,0.6)!important}
.drawer-icon{transform:scale(.55);color:#E5C070!important;filter:drop-shadow(0 0 2px rgba(50,10,0,0.8))!important}
#send_form{display:flex;flex-wrap:wrap;align-items:center;width:94%!important;max-width:800px;margin:10px auto!important;background:#2F0A0A!important;border:1px solid #C89D3B!important;border-radius:0!important;box-shadow:4px 4px 0 #4F1414!important}
#nonQRFormItems{padding:4px 12px!important;position:relative;display:flex;flex-direction:row;column-gap:5px;order:25;width:100%;min-height:40px!important;align-items:center;overflow:hidden;background-color:#2F0A0A!important;border:none!important;box-shadow:none!important;z-index:50}
.qr--buttons{opacity:0;visibility:hidden;max-height:0;margin:0!important;padding:0!important;transform:translateY(15px);transition:all .3s cubic-bezier(.2,1,.3,1);overflow:hidden}
#send_form:focus-within .qr--buttons{opacity:1;visibility:visible;max-height:300px;margin-bottom:8px!important;transform:translateY(0);pointer-events:auto}
#rightSendForm>div:not(.mes_stop),#leftSendForm>div{transform:scale(.6)!important;color:#D6A841}
#send_textarea{background:0 0!important;border:0!important;box-shadow:none!important;color:#F2E6D5!important}#send_textarea::placeholder,#send_textarea::-webkit-input-placeholder{color:transparent!important;opacity:0!important;-webkit-text-fill-color:transparent!important}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before{content:"如果有多一張船票 你會唔會同我一齊走"!important;/* 💜 */position:absolute!important;top:50%!important;left:55%!important;transform:translate(-50%,-50%)!important;font-style:normal!important;font-size:10px!important;pointer-events:none!important;z-index:10!important;white-space:nowrap!important;color:#D2AA5C!important;letter-spacing:1px}
#chat{-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 15px,#000 calc(100% - 25px),transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 15px,#000 calc(100% - 25px),transparent 100%)}
.mes_reasoning_details{width:100%!important;margin:15px 0!important;border:0!important;background:0 0!important;overflow:visible!important}
.mes_reasoning_header,.mes_reasoning_summary,.mes_reasoning_header_text{background:#341010!important;background-image:none!important;box-shadow:none!important;border-radius:0!important}
.mes_reasoning_summary{width:100%!important;box-sizing:border-box!important;border:1px solid #A87528!important;border-left:4px solid #D4A43A!important;padding:8px 15px!important;color:#F2E6D5!important;position:relative!important;display:flex!important;align-items:center!important;min-height:32px!important;cursor:pointer!important;box-shadow:3px 3px 0 #4F1414!important;justify-content:flex-start!important}
/* 保持图标原色 */
.mes_reasoning_summary::after{content:''!important;position:absolute;left:8px;top:50%;transform:translateY(-50%)!important;width:18px;height:12px;background:url('https://files.catbox.moe/dtkz8w.png')center/contain no-repeat!important;filter:none!important}
.mes_reasoning{width:100%!important;box-sizing:border-box!important;background:#2B0C0C!important;border:1px dashed #A87528!important;border-top:0!important;color:#D8BC8C!important;font-size:.9em!important;line-height:1.7!important;padding:15px!important;margin:0!important}
.mes_reasoning_header_icon,.mes_reasoning_details summary::marker{position:absolute!important;right:10px!important;top:50%;transform:translateY(-50%)!important;color:#D6A841!important}

/* ★3. 文字美化 */
/* 加粗 */
.mes_text strong{color:#FFF2D8!important;font-weight:900!important;background:none!important;border-bottom:2px solid #E0B354!important;text-shadow:0 0 8px rgba(180,100,20,0.5)!important;padding:0 2px!important;letter-spacing:1px!important}
/* 斜体 */
.mes_text em{color:#E8CFA0!important;font-style:italic!important;letter-spacing:1px!important;padding:0 4px!important;position:relative!important}
/* 短引用：日系框注风格 */
q{background:transparent!important;color:#F2E6D5!important;border:1px solid #D4A43A!important;padding:2px 8px!important;font-style:normal!important;margin:0 4px!important;display:inline-!important;box-shadow:2px 2px 0 rgba(180,120,20,0.4)!important}
/* 代码：极高对比度底色 */
:not(pre)>code{background:#F0DEC0!important;color:#2F0A0A!important;padding:2px 8px!important;border:none!important;margin:0 2px!important;font-weight:900!important;box-shadow:2px 2px 0 #B47D2A!important}
/* 块引用：电影台词/剧本分镜排版 */
blockquote{margin:30px 0!important;padding:20px 20px 20px 25px!important;background:linear-gradient(90deg, rgba(50,20,20,0.8) 0%, rgba(30,10,10,0) 100%)!important;border:none!important;border-left:4px solid #D4A43A!important;position:relative!important;display:block!important;box-shadow:none!important;color:#EAD9B5!important;font-style:normal!important;line-height:2!important}
blockquote::before{content:'维多利亚'!important;/* 💜 */position:absolute;top:-10px;left:15px;background:#3C0E0E;color:#E5C070;border:1px solid #D4A43A;font-size:9px;padding:2px 10px;letter-spacing:2px;font-weight:700!important;box-shadow:2px 2px 0 rgba(180,120,20,0.4)!important}
/* 代码块 */
pre{background:#1E0505!important;color:#EAD9B5!important;border:1px solid #A87528!important;border-left:4px solid #B5822A!important;box-shadow:5px 5px 0 #4F1414!important;margin:25px 0!important;padding:35px 15px 15px!important;position:relative!important}
pre code,pre span{background:0 0!important;color:inherit!important;text-shadow:none!important}
pre::before{content:'饰演你旧年共寻梦的恋人。'!important;/* 💜 */position:absolute;top:6px;left:30px;font-size:9px!important;font-weight:700!important;color:#D6B06A!important;background:transparent!important;padding:0!important;letter-spacing:2px}
/* 保持图标原色 */
pre::after{content:''!important;position:absolute;top:5px;left:8px;width:16px;height:16px;background:url('https://files.catbox.moe/dtkz8w.png')center/contain no-repeat!important;filter:none!important;z-index:10}

/* ★4. 弹窗 (Toast) 美化 */
#toast-container>.toast{color:#F7E9D0!important;background:#2F0A0A!important;border:1px solid #C89D3B!important;outline:none!important;box-shadow:6px 6px 0 #4F1414!important;padding:15px 15px 15px 45px!important;border-radius:0!important;position:relative!important;overflow:visible!important;text-shadow:0 0 4px rgba(30,5,0,0.7)!important}
#toast-container>.toast::after{content:"弹窗来咯òᆺó";/* 💜 */position:absolute;right:8px;bottom:4px;font-size:7px;color:#D8AA5A;letter-spacing:1px}
/* 保持图标原色 */
#toast-container>.toast::before{content:''!important;position:absolute!important;left:18px!important;top:50%!important;transform:translateY(-50%)!important;width:16px!important;height:16px!important;background:url('https://files.catbox.moe/dtkz8w.png')center/contain no-repeat!important;filter:none!important}
#toast-container>.toast-success::before{filter:none!important}
#toast-container>.toast-error::before{background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg')center/contain no-repeat!important;width:16px!important;height:16px!important;left:14px!important;top:50%!important;filter:grayscale(1) contrast(1.2) invert(.8)!important}
#toast-container>.toast-info::before{filter:none!important}
#toast-container>.toast-warning::before{background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg')center/contain no-repeat!important;width:16px!important;height:16px!important;left:14px!important;top:50%!important;filter:grayscale(1) opacity(.8) invert(.8)!important}
